const input =
  $('Receive Evidence Resolution Request')
    .first()
    .json;

const request =
  $('Get Evidence Request')
    .first()
    .json || {};

const requestFound =
  Boolean(
    String(
      request.evidence_request_id || ''
    ).trim()
  );

const caseMatches =
  String(
    request.case_run_id || ''
  ).trim() ===
  String(
    input.case_run_id || ''
  ).trim();

const versionMatches =
  Number(
    request.submission_version
  ) ===
  Number(
    input.submission_version
  );

const requestStatus =
  String(
    request.status || ''
  )
    .trim()
    .toUpperCase();

const permittedStatuses = [
  'RECEIVED',
  'PARTIALLY_RECEIVED',
  'INSUFFICIENT',
];

const statusPermitted =
  permittedStatuses.includes(
    requestStatus
  );

return [
  {
    json: {
      request_valid:
        requestFound &&
        caseMatches &&
        versionMatches &&
        statusPermitted,

      request_found:
        requestFound,

      case_matches:
        caseMatches,

      version_matches:
        versionMatches,

      status_permitted:
        statusPermitted,

      current_request_status:
        requestStatus,

      evidence_request_id:
        input.evidence_request_id,

      case_run_id:
        input.case_run_id,

      submission_version:
        Number(
          input.submission_version
        ),
    },
  },
];

const records =
  $input
    .all()
    .map(item => item.json)
    .filter(row =>
      String(
        row.evidence_id || ''
      ).trim()
    );

const activeRecords =
  records.filter(row => {
    const status =
      String(
        row.validation_status || ''
      )
        .trim()
        .toUpperCase();

    return ![
      'REJECTED',
      'SUPERSEDED',
    ].includes(status);
  });

return [
  {
    json: {
      evidence_records_exist:
        activeRecords.length > 0,

      evidence_record_count:
        activeRecords.length,

      evidence_ids:
        activeRecords
          .map(row =>
            row.evidence_id
          )
          .filter(Boolean),
    },
  },
];

const request =
  $('Get Evidence Request')
    .first()
    .json;

const caseRow =
  $('Get Evidence Case')
    .first()
    .json;

const evidenceRecords =
  $('Get Evidence Records')
    .all()
    .map(item => item.json)
    .filter(row =>
      String(
        row.evidence_id || ''
      ).trim()
    )
    .filter(row => {
      const status =
        String(
          row.validation_status || ''
        )
          .trim()
          .toUpperCase();

      return ![
        'REJECTED',
        'SUPERSEDED',
      ].includes(status);
    });

let requestedItems = [];

try {
  requestedItems =
    JSON.parse(
      request.requested_items_json ||
      '[]'
    );
} catch {
  requestedItems = [
    String(
      request.requested_items_json ||
      ''
    ),
  ].filter(Boolean);
}

return [
  {
    json: {
      evidence_request: {
        evidence_request_id:
          request.evidence_request_id,

        case_run_id:
          request.case_run_id,

        submission_version:
          Number(
            request.submission_version || 1
          ),

        originating_check_type:
          request.originating_check_type,

        originating_reason_code:
          request.originating_reason_code,

        evidence_channel:
          request.evidence_channel,

        requested_items:
          requestedItems,

        attempt_count:
          Number(
            request.attempt_count || 0
          ),

        max_attempts:
          Number(
            request.max_attempts || 3
          ),
      },

      case_context: {
        case_run_id:
          caseRow.Case_Run_ID,

        logical_case_id:
          caseRow.Case_ID,

        country:
          caseRow.Country,

        request_type:
          caseRow.Request_Type,

        business_name:
          caseRow.Business_Name_Submitted,

        business_identifier:
          caseRow.Business_Identifier_Submitted,

        customer_id:
          caseRow.Customer_ID,

        representative_name:
          caseRow.Representative_Name,

        representative_role:
          caseRow.Representative_Role,

        requested_authority:
          caseRow.Requested_Authority,

        request_narrative:
          caseRow.Customer_Request_Narrative,
      },

      evidence_records:
        evidenceRecords.map(row => ({
          evidence_id:
            row.evidence_id,

          evidence_type:
            row.evidence_type,

          evidence_source:
            row.evidence_source,

          file_name:
            row.file_name,

          mime_type:
            row.mime_type,

          evidence_text:
            row.evidence_text,

          structured_data_json:
            row.structured_data_json,

          provided_at:
            row.provided_at,
        })),
    },
  },
];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "resolution_status": {
      "type": "string",
      "enum": [
        "RESOLVED",
        "PARTIAL",
        "INSUFFICIENT",
        "CONTRADICTORY"
      ],
      "description": "The resolution of the exact originating evidence gap."
    },
    "resolved": {
      "type": "boolean",
      "description": "True only when resolution_status is RESOLVED."
    },
    "supported_facts": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Facts explicitly supported by the submitted evidence."
    },
    "remaining_gaps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Relevant evidence requirements that remain unresolved."
    },
    "reason_codes": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Reason codes supporting the evidence-resolution result."
    },
    "recommended_next_action": {
      "type": "string",
      "description": "The next operational action after this evidence assessment."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Confidence in the evidence-resolution result."
    }
  },
  "required": [
    "resolution_status",
    "resolved",
    "supported_facts",
    "remaining_gaps",
    "reason_codes",
    "recommended_next_action",
    "confidence"
  ]
}

parameters.jsCode:
const context =
  $('Prepare Resolution Context')
    .first()
    .json;

const request =
  context.evidence_request;

// The Basic LLM Chain may return the parsed object directly,
// or place it under output, text, or response.
let resolution =
  $json.output ??
  $json.text ??
  $json.response ??
  $json;

// Handle nested parser output.
if (
  resolution &&
  typeof resolution === 'object' &&
  !Array.isArray(resolution) &&
  resolution.output !== undefined
) {
  resolution =
    resolution.output;
}

// Handle JSON returned as text.
if (typeof resolution === 'string') {
  const cleaned =
    resolution
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');

  try {
    resolution =
      JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Evidence-resolution output could not be parsed as JSON: ${error.message}`
    );
  }
}

if (
  !resolution ||
  typeof resolution !== 'object' ||
  Array.isArray(resolution)
) {
  throw new Error(
    'Evidence-resolution output is not a valid JSON object.'
  );
}

function stringArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(item => {
      if (typeof item === 'string') {
        return item.trim();
      }

      if (
        item !== null &&
        item !== undefined
      ) {
        return JSON.stringify(item);
      }

      return '';
    })
    .filter(Boolean);
}

const permittedResolutionStatuses = [
  'RESOLVED',
  'PARTIAL',
  'INSUFFICIENT',
  'CONTRADICTORY',
];

let resolutionStatus =
  String(
    resolution.resolution_status ||
    'INSUFFICIENT'
  )
    .trim()
    .toUpperCase();

if (
  !permittedResolutionStatuses.includes(
    resolutionStatus
  )
) {
  resolutionStatus =
    'INSUFFICIENT';
}

const checkType =
  String(
    request.originating_check_type ||
    'REQUEST_CLARIFICATION'
  )
    .trim()
    .toUpperCase();

const sequenceMap = {
  REQUEST_CLARIFICATION: 0,
  CUSTOMER_CONFIRMATION: 0,
  SALES_CONFIRMATION: 0,
  DOCUMENT_EXTRACTION: 1,
  BUSINESS_VALIDATION: 2,
  IDENTITY_VALIDATION: 3,
  AUTHORITY_VALIDATION: 4,
  SYSTEM_DATA_CHECK: 5,
  FINANCIAL_CHECK: 6,
  FINAL_VERIFICATION: 7,
};

const sequence =
  sequenceMap[checkType] ?? 0;

const currentAttemptCount =
  Number(
    request.attempt_count || 0
  ) + 1;

const maxAttempts =
  Number(
    request.max_attempts || 3
  );

const supportedFacts =
  stringArray(
    resolution.supported_facts
  );

const remainingGaps =
  stringArray(
    resolution.remaining_gaps
  );

const modelReasonCodes =
  stringArray(
    resolution.reason_codes
  );

const evidenceReferences =
  context.evidence_records
    .map(record =>
      String(
        record.evidence_id || ''
      ).trim()
    )
    .filter(Boolean);

const rawConfidence =
  Number(
    resolution.confidence
  );

const confidence =
  Number.isFinite(rawConfidence)
    ? Math.max(
        0,
        Math.min(
          1,
          rawConfidence
        )
      )
    : 0;

let status;
let terminalOutcome;
let ruleId;
let primaryResolutionReason;
let humanReviewRequired;
let requestStatus;
let retryAllowed;
let escalationRequired;
let fallbackNextAction;

switch (resolutionStatus) {
  case 'RESOLVED':
    status =
      'PASS';

    /*
    EVID-001 resolves the originating check.
    It is not a fifth whole-case outcome.
    */
    terminalOutcome =
      '';

    ruleId =
      'EVID-001';

    primaryResolutionReason =
      'ADDITIONAL_EVIDENCE_ACCEPTED';

    humanReviewRequired =
      false;

    requestStatus =
      'ACCEPTED';

    retryAllowed =
      false;

    escalationRequired =
      false;

    fallbackNextAction =
      'Resume processing from the next incomplete mandatory check.';

    break;

  case 'CONTRADICTORY':
    status =
      'INCONCLUSIVE';

    terminalOutcome =
      'MANUAL_REVIEW';

    ruleId =
      'EVID-003';

    primaryResolutionReason =
      'ADDITIONAL_EVIDENCE_CONTRADICTORY';

    humanReviewRequired =
      true;

    requestStatus =
      'ESCALATED';

    retryAllowed =
      false;

    escalationRequired =
      true;

    fallbackNextAction =
      'Route the case and conflicting evidence to human evidence review.';

    break;

  case 'PARTIAL':
  case 'INSUFFICIENT':
  default:
    status =
      'INCONCLUSIVE';

    terminalOutcome =
      'NEED_MORE_INFORMATION';

    ruleId =
      'EVID-002';

    primaryResolutionReason =
      'ADDITIONAL_EVIDENCE_INSUFFICIENT';

    /*
    EVID-002 itself remains customer-remediable.
    Operational human escalation is created later only when
    the maximum number of attempts has been exhausted.
    */
    humanReviewRequired =
      false;

    retryAllowed =
      currentAttemptCount <
      maxAttempts;

    requestStatus =
      retryAllowed
        ? 'INSUFFICIENT'
        : 'ESCALATED';

    escalationRequired =
      !retryAllowed;

    fallbackNextAction =
      retryAllowed
        ? 'Request the specific remaining evidence and keep the case open.'
        : 'Route the unresolved evidence request to a human evidence reviewer.';

    break;
}

const recommendedNextStep =
  String(
    resolution.recommended_next_action ||
    fallbackNextAction
  ).trim();

const reasonCodes = [
  ...new Set([
    primaryResolutionReason,
    ...modelReasonCodes,
  ]),
];

const resultId =
  `RES-${request.case_run_id}-V${Number(
    request.submission_version || 1
  )}-${checkType}`;

return [
  {
    json: {
      result_id:
        resultId,

      case_run_id:
        request.case_run_id,

      submission_version:
        Number(
          request.submission_version || 1
        ),

      sequence,

      agent_id:
        'SBO.02',

      utility_name:
        'Evidence Resolution Utility',

      /*
      Retain the originating mandatory check type.
      This allows the row to replace the previous failed or
      inconclusive result for that same check.
      */
      check_type:
        checkType,

      status,

      findings: {
        evidence_resolution:
          true,

        evidence_request_id:
          request.evidence_request_id,

        resolution_status:
          resolutionStatus,

        resolved:
          resolutionStatus ===
          'RESOLVED',

        supported_facts:
          supportedFacts,

        remaining_gaps:
          remainingGaps,

        evidence_count:
          evidenceReferences.length,
      },

      reason_codes:
        reasonCodes,

      evidence_references:
        evidenceReferences,

      confidence,

      human_review_required:
        humanReviewRequired,

      recommended_next_step:
        recommendedNextStep,

      rule_ids: [
        ruleId,
      ],

      rule_status_used:
        'CONFIRMED_POC',

      is_terminal:
        Boolean(
          terminalOutcome
        ),

      terminal_outcome:
        terminalOutcome,

      evidence_request_id:
        request.evidence_request_id,

      resolution_status:
        resolutionStatus,

      current_attempt_count:
        currentAttemptCount,

      max_attempts:
        maxAttempts,

      retry_allowed:
        retryAllowed,

      escalation_required:
        escalationRequired,

      evidence_request_status:
        requestStatus,
    },
  },
];
